public static void main(String[] args) {
  Scanner sc = new Scanner(System.in);
  int n = sc.nextInt();
  int[] A = new int[2 * n];
  for (int i = 0; i < 2 * n; i++) {
    A[i] = sc.nextInt();
  }
  int count = 0;
  for (int i = 1; i <= n; i++) {
    int first = -1, second = -1;
    for (int j = 0; j < 2 * n; j++) {
      if (A[j] == i) {
        if (first == -1) {
          first = j;
        } else {
          second = j;
          break;
        }
      }
    }
    if (second - first == 2) {
      count++;
    }
  }
  System.out.print(count);
}

